const express = require('express');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express();
const TRACE_STORAGE = process.env.TRACE_DIR || '/var/playwright/traces';

app.get('/api/test-runs/:runId/trace-artifact', async (req, res) => {
  const { runId } = req.params;

  // Scope test execution lookup to authenticated organization
  const testRun = await knex('e2e_test_runs')
    .where({ id: runId, organization_id: req.user.organization_id })
    .first();
  if (!testRun) {
    return res.status(404).json({ error: 'Test run record not found' });
  }

  const traceFilePath = path.join(TRACE_STORAGE, `${runId}.zip`);
  if (!fs.existsSync(traceFilePath)) {
    return res.status(404).json({ error: 'Trace artifact missing or expired' });
  }

  res.setHeader('Content-Type', 'application/zip');
  res.setHeader('Content-Disposition', `attachment; filename="trace_${runId}.zip"`);
  return fs.createReadStream(traceFilePath).pipe(res);
});

module.exports = app;
